SELECT 
FROM marketing_task_export_job
WHERE id = #{id}
  AND created_by = #{createdBy}
  AND export_mode = 'HYPERLINK_ACCOUNT_STATS'

SELECT 
FROM marketing_task_export_job
WHERE tenant_id = #{tenantId}
  AND created_by = #{createdBy}
  AND request_hash = #{requestHash}
  AND export_mode = 'HYPERLINK_ACCOUNT_STATS'
  AND status IN ('PENDING', 'PROCESSING')
ORDER BY id DESC
LIMIT 1

mapper.update:
UPDATE marketing_task_export_job
SET status = 'PROCESSING', lease_until = #{leaseUntil}, claim_token = #{claimToken},
    attempt_count = attempt_count + 1, error_message = NULL, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{id}
  AND export_mode = 'HYPERLINK_ACCOUNT_STATS' AND attempt_count < 3
  AND (status = 'PENDING' OR (status = 'PROCESSING' AND lease_until < #{now}))

UPDATE marketing_task_export_job
SET lease_until = #{leaseUntil}, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{id} AND status = 'PROCESSING'
  AND export_mode = 'HYPERLINK_ACCOUNT_STATS' AND claim_token = #{claimToken}

UPDATE marketing_task_export_job
SET status = 'FAILED', error_message = #{errorMessage}, lease_until = NULL,
    claim_token = NULL, finished_at = #{finishedAt}, updated_at = #{finishedAt}
WHERE tenant_id = #{tenantId} AND id = #{id} AND status = 'PROCESSING'
  AND export_mode = 'HYPERLINK_ACCOUNT_STATS' AND claim_token = #{claimToken}

UPDATE marketing_task_export_job
SET status = 'EXPIRED', storage_key = NULL, content_type = NULL,
    file_size = NULL, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{id}
  AND export_mode = 'HYPERLINK_ACCOUNT_STATS' AND status = 'SUCCESS'
  AND expires_at <= #{now} AND storage_key = #{storageKey}
